import DatabaseUtils from '../../../storage/mongodb/DatabaseUtils';
import { Ocpp201TransactionMapping } from '../types/Ocpp201Types';
import Tenant from '../../../types/Tenant';
import global from '../../../types/GlobalType';

const COLLECTION_NAME = 'ocpp201transactions';

type Ocpp201TransactionMappingMDB = Omit<Ocpp201TransactionMapping, 'id'> & { _id: string };

// Persists the link between an OCPP 2.0.1 transaction (string ID generated by the charging station)
// and the platform transaction (numeric ID generated by the CSMS)
export default class Ocpp201TransactionStorage {
  private static readonly tenantsWithIndexes = new Set<string>();

  public static buildMappingID(chargingStationID: string, transactionId: string): string {
    return `${chargingStationID}~${transactionId}`;
  }

  public static async getMapping(tenant: Tenant, chargingStationID: string, transactionId: string): Promise<Ocpp201TransactionMapping | null> {
    DatabaseUtils.checkTenantObject(tenant);
    const mappingMDB = await Ocpp201TransactionStorage.getCollection(tenant)
      .findOne({ _id: Ocpp201TransactionStorage.buildMappingID(chargingStationID, transactionId) });
    return Ocpp201TransactionStorage.fromMDB(mappingMDB);
  }

  public static async getMappingByPlatformTransactionID(tenant: Tenant, chargingStationID: string,
      platformTransactionID: number): Promise<Ocpp201TransactionMapping | null> {
    DatabaseUtils.checkTenantObject(tenant);
    await Ocpp201TransactionStorage.ensureIndexes(tenant);
    const mappingMDB = await Ocpp201TransactionStorage.getCollection(tenant)
      .findOne({ chargingStationID, platformTransactionID });
    return Ocpp201TransactionStorage.fromMDB(mappingMDB);
  }

  public static async getOngoingMappingsOfChargingStation(tenant: Tenant, chargingStationID: string): Promise<Ocpp201TransactionMapping[]> {
    DatabaseUtils.checkTenantObject(tenant);
    await Ocpp201TransactionStorage.ensureIndexes(tenant);
    const mappingsMDB = await Ocpp201TransactionStorage.getCollection(tenant)
      .find({ chargingStationID, ended: false })
      .sort({ createdOn: -1 })
      .toArray();
    return mappingsMDB.map((mappingMDB) => Ocpp201TransactionStorage.fromMDB(mappingMDB));
  }

  public static async saveMapping(tenant: Tenant, mapping: Ocpp201TransactionMapping): Promise<void> {
    DatabaseUtils.checkTenantObject(tenant);
    await Ocpp201TransactionStorage.ensureIndexes(tenant);
    const { id, ...mappingData } = mapping;
    mappingData.lastChangedOn = new Date();
    await Ocpp201TransactionStorage.getCollection(tenant)
      .replaceOne({ _id: id }, mappingData, { upsert: true });
  }

  private static getCollection(tenant: Tenant) {
    return global.database.getCollection<Ocpp201TransactionMappingMDB>(tenant.id, COLLECTION_NAME);
  }

  private static async ensureIndexes(tenant: Tenant): Promise<void> {
    if (Ocpp201TransactionStorage.tenantsWithIndexes.has(tenant.id)) {
      return;
    }
    const collection = Ocpp201TransactionStorage.getCollection(tenant);
    await collection.createIndex({ chargingStationID: 1, platformTransactionID: 1 });
    await collection.createIndex({ chargingStationID: 1, ended: 1 });
    Ocpp201TransactionStorage.tenantsWithIndexes.add(tenant.id);
  }

  private static fromMDB(mappingMDB: Ocpp201TransactionMappingMDB | null): Ocpp201TransactionMapping | null {
    if (!mappingMDB) {
      return null;
    }
    const { _id, ...mappingData } = mappingMDB;
    return { id: _id, ...mappingData };
  }
}
